        b = tail(stack, 1)
        a = tail(stack, 2)[1]
        stack = c(head(stack, -2), eval(parse(text = paste0(a, t, b))))
      }
    } else {
      stack = c(stack, as.numeric(t))
    }
  }
  stack[1]
}

