def eval_rpn(tokens):
    stack = []
    for t in tokens:
        if t in '+-*/':
            if len(stack) &gt; 2:
                res = stack[0]
                for n in stack[1:]:
                    res = eval(f"{res}{t}{n}")
                stack = [res]
            else:
                b = stack.pop()
                a = stack.pop()
                stack.append(eval(f"{a}{t}{b}"))
        else:
            stack.append(int(t))
    return stack[0]

